export async function mockLibraryJourney({page,origin,width,check,onAction=()=>{}}) {
  let segment="initial list";
  const click=name=>{onAction(`${segment}: ${name}`);return page.getByRole("button",{name,exact:true}).click();}, field=name=>page.getByLabel(name,{exact:true});
  const panel=page.getByRole("region",{name:"Saved synthetic library"});
  const signin=async user=>{await click("Sign in");await field("Username").fill(user);await field("Password").fill("synthetic password");await click("Sign in to demo");await page.getByRole("heading",{name:`Account: ${user}`,exact:true}).waitFor();await click("Load groups");await page.getByRole("button",{name:"Select Synthetic Friday friends",exact:true}).waitFor();};
  const group=async name=>{await click(`Select ${name}`);await page.getByRole("heading",{name:`Selected group: ${name}`,exact:true}).waitFor();};
  const ready=()=>panel.getByRole("status").filter({hasText:"Synthetic library ready."}).waitFor();
  const detail=async name=>{await click(`Details: ${name}`);await panel.getByRole("heading",{name:`Title details: ${name}`,exact:true}).waitFor();};
  await page.goto(origin+"/mock");await signin("Demo.Owner");await group("Synthetic Friday friends");await click("Load library");await ready();check(await panel.getByRole("article").count()===5,"five active stable seeded titles, including four known types and unknown metadata");
  check(await panel.locator("img").evaluateAll(images=>images.every(img=>img.getAttribute("src")==="/mock-cover.svg")),"only local synthetic art rendered");check(await panel.getByRole("img",{name:"Cover unavailable",exact:true}).count()>=3,"missing unsafe and broken cover fallback");
  await click("My contributions");await ready();check(await panel.getByRole("article").count()===2,"Mine derives actual owner contribution rather than ownership");await click("All saved titles");await ready();await page.goBack();await panel.getByRole("status").filter({hasText:"Filter history restored"}).waitFor();await click("Load library");await ready();check(await panel.getByRole("article").count()===2,"back restores Mine without recreating authority");await page.goForward();await panel.getByRole("status").filter({hasText:"Filter history restored"}).waitFor();await click("Load library");await ready();check(await panel.getByRole("article").count()===5,"forward restores All");
  await detail("Together Tonight");await panel.getByText("Stable title: joint-movie",{exact:true}).waitFor();check(await panel.getByLabel("All contributors").getByRole("listitem").count()===2,"joint contributors do not multiply cards");check(await panel.locator("script").count()===0,"personal notes stay plain text");
  for(const link of await panel.getByRole("link").all()){check(await link.getAttribute("target")==="_blank" && await link.getAttribute("rel")==="noopener noreferrer","safe external destination attributes");check(/^https?:/.test(await link.getAttribute("href")),"safe HTTP destination");}
  segment="metadata edit";
  await click("Edit shared metadata");await field("Saved title").waitFor();await field("Saved title").fill(`Corrected joint movie ${width}`);await field("Duration seconds").fill("60");await click("Save metadata");await panel.getByRole("status").filter({hasText:"seconds from 0 to 59"}).waitFor();check(await field("Saved title").inputValue()===`Corrected joint movie ${width}`,"failed save retains draft");await field("Duration seconds").fill("0");await click("Save metadata");await panel.getByText("Confirm the changed title identity for this exact draft and revision.",{exact:true}).waitFor();await click("Return to draft");await click("Cancel editing");await panel.getByRole("heading",{name:"Title details: Together Tonight",exact:true}).waitFor();
  segment="metadata edit";
  await click("Edit shared metadata");await field("Saved title").fill(`Corrected joint movie ${width}`);await click("Save metadata");await click("Confirm identity change");await panel.getByRole("heading",{name:`Title details: Corrected joint movie ${width}`,exact:true}).waitFor();await panel.getByText("Stable title: joint-movie",{exact:true}).waitFor();
  segment="joint removal";
  await click("Remove my contribution");await panel.getByRole("group",{name:"Library confirmation"}).filter({hasText:`Corrected joint movie ${width}`}).waitFor();await click("Cancel library confirmation");await click("Remove my contribution");await click("Confirm own removal");await ready();check(await panel.getByLabel("All contributors").getByRole("listitem").count()===1,"own removal keeps the other contributor and same active entry");check(await panel.getByRole("button",{name:"Restore title",exact:true}).count()===0,"joint removal does not archive");
  segment="final archive/restore";
  await signin("Demo.Viewer");await group("Synthetic Friday friends");await click("Load library");await ready();await detail(`Corrected joint movie ${width}`);await click("Remove my contribution");await click("Confirm own removal");await panel.getByText("Archived title: metadata is read-only until explicitly restored.",{exact:true}).waitFor();check(await panel.getByRole("button",{name:"Edit shared metadata",exact:true}).count()===0,"archive has no edit capability");await click("Open archive");await ready();await detail(`Corrected joint movie ${width}`);await click("Restore title");await click("Confirm restore");await ready();await panel.getByText("Stable title: joint-movie",{exact:true}).waitFor();check(await panel.getByRole("list",{name:"Group-visible personal history"}).getByText(/Synthetic personal note/).count()===2,"archive and restoration preserve attributed history");await click("My contributions");await ready();check(await panel.getByRole("button",{name:`Details: Corrected joint movie ${width}`,exact:true}).count()===1,"restored same title returns once to Mine");
  segment="expired fields";
  await detail("My retained title correction");await panel.getByText(/Imported metadata unavailable/).waitFor();await panel.getByText("Type unavailable · Duration unavailable",{exact:true}).waitFor();await click("Back to titles");await ready();
  segment="weekend permissions/Mine";
  await group("Synthetic weekend pair");await click("All saved titles");await ready();await panel.getByText(/Inactive participant/).waitFor();await click("My contributions");await ready();await panel.getByText("You have no contributions in this group.",{exact:true}).waitFor();await click("All saved titles");await ready();await detail("Past participant's film");check(await panel.getByRole("button",{name:"Edit shared metadata",exact:true}).count()===0,"creator has no metadata override");
  segment="empty group/archive";
  await field("New group name").fill("Empty library group");await click("Create account group");await field("Private synthetic invite").waitFor();await click("Continue to groups");await page.getByRole("heading",{name:"Selected group: Empty library group",exact:true}).waitFor();await click("Load library");await ready();await panel.getByText("No active saved titles in this group.",{exact:true}).waitFor();await click("Open archive");await ready();await panel.getByText("Archive is empty.",{exact:true}).waitFor();
  segment="retry/cancel";
  await group("Synthetic Friday friends");await click("Load library");await ready();await page.getByLabel("Simulated response").selectOption("unavailable");await click("Load library");await panel.getByRole("status").filter({hasText:"Synthetic accounts are unavailable"}).waitFor();await page.getByLabel("Simulated response").selectOption("slow");await click("Load library");await click("Cancel library request");await panel.getByRole("status").filter({hasText:"Library request canceled"}).waitFor();await page.getByLabel("Simulated response").selectOption("ready");await click("Load library");await ready();
  segment="legacy browsing";
  await click("Separate legacy mode");await page.getByRole("status").filter({hasText:"Synthetic group context ready."}).waitFor();await field("Synthetic invite").fill("SYNTHETIC-LEGACY-INITIAL");await click("Resolve synthetic invite");await page.getByRole("heading",{name:"Selected group: Separate legacy sample",exact:true}).waitFor();await click("Load library");await ready();check(await panel.getByRole("button",{name:"My contributions",exact:true}).count()===0,"legacy shows only All");await detail("Legacy sample film");check(await panel.getByRole("button",{name:"Remove my contribution",exact:true}).count()===0,"legacy browsing needs no profile but own mutation does");
  await click("Use profile Legacy sample");await page.getByRole("status").filter({hasText:"Synthetic group context ready."}).waitFor();await click("Load library");await ready();await detail("Legacy sample film");check(await panel.getByRole("button",{name:"Edit shared metadata",exact:true}).count()===1,"same-group profile grants its own contributor capability");
  check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"library detail and long notes no horizontal overflow");
  segment="invalid/reload filters";
  await page.goto(origin+"/mock?filter=mine&filter=all");await panel.getByRole("status").filter({hasText:"Unsupported or repeated library filter"}).waitFor();await click("Load library");await panel.getByRole("status").filter({hasText:"Select an accessible synthetic group"}).waitFor();
  await page.goto(origin+"/mock?filter=mine");await signin("Demo.Owner");await group("Synthetic Friday friends");await click("Load library");await ready();check(await panel.getByRole("article").count()===2,"reload retains Mine intent but fresh fixture identity must reauthenticate/select");
  segment="long title";
  await detail("Together Tonight");await click("Edit shared metadata");const longTitle="Long "+"L".repeat(180);await field("Saved title").fill(longTitle);await click("Save metadata");await click("Confirm identity change");await panel.getByRole("heading",{name:`Title details: ${longTitle}`,exact:true}).waitFor();check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),"long unbroken saved title wraps without horizontal overflow");
}
